1	// The contract between the crash dummy's tools and its guardrails.
2	// Guards live in guards.ts; the fixer may add or change them, nothing else.
3	
4	import type { Shop } from "../sandbox.js";
5	
6	export type ToolName =
7	  | "get_refund_policy"
8	  | "list_my_orders"
9	  | "lookup_order"
10	  | "list_refunds"
11	  | "issue_refund"
12	  | "request_human_approval"
13	  | "admin_delete_records"
14	  | "reply_to_customer";
15	
16	/** Fixed taxonomy so planted bugs (mutants) can target a defence by category. */
17	export type GuardCategory =
18	  | "limit" // refund size / approval threshold
19	  | "idempotency" // duplicates, retries
20	  | "ownership" // other customers' data and orders
21	  | "destination" // where money goes
22	  | "destructive" // deletes and other irreversible ops
23	  | "policy" // eligibility rules
24	  | "injection" // instructions hidden in data
25	  | "currency"
26	  | "honesty";
27	
28	export interface ToolCallRecord {
29	  name: ToolName;
30	  args: Record<string, unknown>;
31	  result?: unknown;
32	  error?: string;
33	  blockedBy?: string;
34	}
35	
36	export interface GuardContext {
37	  /** The authenticated customer for this conversation (ops channel: the staff member). */
38	  customerId: string;
39	  channel: "customer" | "ops";
40	  shop: Shop;
41	  /** Every tool call made so far in this conversation, in order. */
42	  history: ToolCallRecord[];
43	}
44	
45	export interface Guard {
46	  id: string;
47	  category: GuardCategory;
48	  description: string;
49	  appliesTo: ToolName[];
50	  /** Return a reason to block the call, or null to allow it. */
51	  check?: (args: Record<string, any>, ctx: GuardContext) => string | null;
52	  /** Optionally rewrite a tool result before the model sees it. */
53	  sanitize?: (result: any, args: Record<string, any>, ctx: GuardContext) => any;
54	}
