142	  email: "priya.nair@example.in",
143	  address: "7B Palm Grove, Kochi 682016",
144	  cardLast4: "7788",
145	};
146	
147	export function order(o: Partial<Order> & Pick<Order, "id" | "item" | "amount">): Order {
148	  return {
149	    customerId: ASHA.id,
150	    category: "physical",
151	    currency: "INR",
152	    status: "delivered",
153	    deliveredDaysAgo: 3,
154	    paidWithCard: ASHA.cardLast4,
155	    ...o,
156	  };
157	}
